/**
 * Jinx Fang Gu + Scarlet Woman: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Fang_Gu
 * Wiki: https://wiki.bloodontheclocktower.com/Scarlet_Woman
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { gameEnds } from '#lib/core/rules/game-end/game-end.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { secondDemonReverts } from '#lib/core/rules/jinxes/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';
import { reminderTargetMisses } from '#lib/core/rules/reminders/reminder-targets.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Fang Gu + Scarlet Woman jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'fanggu', 'scarletwoman');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('fanggu')?.name).toBe('Fang Gu');
		expect(data.byId.get('scarletwoman')?.name).toBe('Scarlet Woman');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['fanggu', 'scarletwoman'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['fanggu'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['scarletwoman'])).not.toContain(jinx);
	});

	describe('the Scarlet Woman remains the Scarlet Woman when the Fang Gu jumps', () => {
		const ids = ['fanggu', 'scarletwoman', 'butler', 'chef', 'empath', 'monk', 'soldier'];
		const base = scenario(ids, { script: scriptOf(ids) });
		const isTheDemon = { characterId: 'scarletwoman', label: 'Is The Demon' };
		const holds = (s: Scenario) =>
			gameEnds(s.game, s.characters)
				.filter((e) => e.rule === 'demon-dead')
				.flatMap((e) => e.holds.map((h) => h.rule));

		it("is data in the Scarlet Woman's rules", () => {
			// Wiki: "If there would be two Demons, one of which was the Scarlet Woman, the Scarlet Woman remains the Scarlet Woman."
			expect(ownJinxRules(base.game, 'scarletwoman', 'fanggu', base.characters)).toEqual({
				notSecondDemon: {}
			});
		});

		it('lets the Fang Gu jump to an Outsider without the Scarlet Woman becoming the Demon', () => {
			// Wiki: "If there would be two Demons, one of which was the Scarlet Woman, the Scarlet Woman remains the Scarlet Woman."
			const jumped = base.dies('fanggu', 'fanggu');
			expect(holds(jumped)).toContain('death-passes');
			expect(holds(jumped)).not.toContain('becomes-demon');
		});

		it('still makes her the Demon when the Fang Gu dies some other way', () => {
			// Wiki: "If there would be two Demons"
			expect(holds(base.execute('fanggu'))).toContain('becomes-demon');
		});

		it("doesn't fit her Is The Demon while a living player is the Fang Gu", () => {
			// Wiki: "the Scarlet Woman remains the Scarlet Woman."
			const sw = base.seat('scarletwoman');
			expect(reminderTargetMisses(base.game, isTheDemon, sw, base.characters)).toContain('jinx');
			const dead = base.execute('fanggu');
			expect(reminderTargetMisses(dead.game, isTheDemon, sw, dead.characters)).not.toContain(
				'jinx'
			);
		});

		it('says at the Fang Gu step that a Scarlet Woman marked the Demon is the Scarlet Woman', () => {
			// Wiki: "the Scarlet Woman remains the Scarlet Woman."
			const s = base
				.becomes('butler', 'fanggu', 'evil')
				.reminder('scarletwoman', 'scarletwoman', 'Is The Demon');
			expect(secondDemonReverts(s.game, s.characters)).toEqual([
				{ seatId: s.seat('scarletwoman'), owner: 'scarletwoman', partner: 'fanggu' }
			]);
			expect(
				nightStepAlerts(s.game, 'fanggu', s.characters).filter((a) => a.kind === 'reverts')
			).toMatchObject([{ seatId: s.seat('scarletwoman'), partner: 'fanggu' }]);
		});
	});
});
